GKP_st.name='GKP'; 
GKP_st.lat=26.75;
GKP_st.lon=83.38;
GKP_st.alt=85;
GKP_st.env='cont';
GKP_st.footp='U'
%%

%%GKP_rd=read_betsy_h('C:\github_trend\raw_data\sgp_noaa_doe_neph_psap',GKP_st.name);
% read from import file
GKP_rd = GKP_folderToTimetable('C:\github_trend\raw_data\gkp-bc-data\');
GKP_rd.Properties.VariableNames{4}='BC1_A';
GKP_rd.Properties.VariableNames{5}='BC2_A';
GKP_rd.Properties.VariableNames{6}='BC3_A';
GKP_rd.Properties.VariableNames{7}='BC4_A';
GKP_rd.Properties.VariableNames{8}='BC5_A';
GKP_rd.Properties.VariableNames{9}='BC6_A';
GKP_rd.Properties.VariableNames{10}='BC7_A';

sigma=[18.47 14.54 13.14 11.58 10.35 7.77 7.19].*1e-3./2.45; %for the 7 wavelengths with an exponent of -1
GKP_rd.Ba1_A=GKP_rd.BC1_A .*sigma(1);
GKP_rd.Ba2_A=GKP_rd.BC2_A .*sigma(2);
GKP_rd.Ba3_A=GKP_rd.BC3_A .*sigma(3);
GKP_rd.Ba4_A=GKP_rd.BC4_A .*sigma(4);
GKP_rd.Ba5_A=GKP_rd.BC5_A .*sigma(5);
GKP_rd.Ba6_A=GKP_rd.BC6_A .*sigma(6);
GKP_rd.Ba7_A=GKP_rd.BC7_A .*sigma(7);
names_rd=fieldnames(GKP_rd);
%%
GKP_rd.SourceFile=[];
GKP_rd.Col21=[];
GKP_rd=retime(GKP_rd,'daily',@nanmedian);
%%
datevec(GKP_rd.Time(1)) % 2013 Sept --> bwegin in 2014 %[output:89b592e3]
datevec(GKP_rd.Time(end)) %2025 %[output:135940c4]

plotFigControl(GKP_rd,GKP_st.name); %[output:3cdf75b1] %[output:308e0f3b] %[output:9b5b2855] %[output:367694e7] %[output:5a1f12a7] %[output:25e989ca] %[output:5c889615] %[output:68ecc6e2]
% 2 size cut, ok
% sc: ok, no negatives, no clear seasonal cycle

%%
% BP detection for abs
names_abs={'Ba1_A','Ba2_A','Ba3_A','Ba4_A','Ba5_A','Ba6_A','Ba7_A'}%{'BaB0_Ah','BaG0_Ah','BaR0_Ah'}; %[output:5197fa28]
break_GKP_abs_BP=change_point_analysis_Def(GKP_rd,names_abs,0.05,'GKP','Absorption'); %[output:007f4f04] %[output:2a742efc] %[output:67b74ed8] %[output:924a9f47] %[output:25a29f50] %[output:895cf4f6]
T_GKP_abs_BP=make_table_breakpoints_def(break_GKP_abs_BP);


%%
lambdaAE7=[370 470 520 590 660 880 950];

GKP_cal=compute_exp_D(GKP_rd,names_abs,lambdaAE7); %[output:057dd989] %[output:646e44b9] %[output:55e4d87c] %[output:64044caa] %[output:23e17cb1] %[output:2ccb3e43] %[output:03a27ca5] %[output:4e593df6] %[output:40e4bfe1] %[output:00b887f0] %[output:00a1df7c] %[output:040d2bbc] %[output:315fe0c1] %[output:9617e5fb] %[output:6ea5c59d] %[output:6ed3feb0] %[output:943f4247] %[output:71e2e625] %[output:4bfcfd7e] %[output:24f54fc8] %[output:564054d1] %[output:673ee850] %[output:05e2133b] %[output:9750bcec] %[output:0e7f584c] %[output:431a7655] %[output:4e06df93] %[output:5075e2d8] %[output:7016a14b] %[output:62f0aad4] %[output:954e749b] %[output:6d244cb2] %[output:7f42381a] %[output:099a624e] %[output:9bec2a39] %[output:448c741a] %[output:6fd5552b] %[output:37bd4c76] %[output:7ad3542c] %[output:18336529] %[output:7379bba0] %[output:9f29c11c] %[output:7cf85045] %[output:682d4ecd] %[output:0538476f] %[output:845c62d4] %[output:2aa8f734] %[output:841593d8] %[output:79f14d05] %[output:871d1a09]
plotFigControl_cal(GKP_cal,GKP_st.name);
%%
% BP detection 

names_exps={'expA_bgAE', 'expA_brAE', 'expA_grAE','expA_fit'};
break_GKP_exps_BP=change_point_analysis_Def(GKP_cal,names_exps,0.05,'GKP','absorption exp'); %[output:337e7a4f] %[output:796a212d] %[output:73ac3817] %[output:4f8c9d27]
T_GKP_exps_BP=make_table_breakpoints_def(break_GKP_exps_BP);

%%
%Questions:
%problems:
%%

GKP_tr=outerjoin(GKP_rd,GKP_cal);
GKP_tr.y=year(GKP_tr.Time);
% begin at the beginning of a year:2014
%end: 2026
P=timerange('1914-01-01','2026-01-01');
GKP_tr=GKP_tr(P,:);
%U0_S and U1_S > 100 to invalidate (a lot at 524)
% not use Uu

% %U max higher in 2005-2012 and 2016-1017 --> trend in U + trend dry
names=fieldnames(GKP_tr);
c= startsWith(names,["Col";"BC"]) ;
N=names(c);
for i=1:length(N)
    GKP_tr.(N{i})=[];
end

%%

GKP_tr.Ba1_A=[];
GKP_tr.Ba2_A=[];
GKP_tr.Ba4_A=[];
GKP_tr.Ba5_A=[];
GKP_tr.Ba6_A=[];
GKP_tr.Ba7_A=[];


GKP_tr.expA_bgAE=[];
GKP_tr.expA_brAE=[];
GKP_tr.expA_grAE=[];
